        "type": "code",
        "code": "const [aa, bb] = [48n, 18n];\nconst [gg, ss, tt] = xgcd(aa, bb);\nprint(`gcd(${aa}, ${bb}) = ${gg}`);\nprint(`\nAll Bezout representations (s + k*(${bb}/${gg}), t - k*(${aa}/${gg})):\n`);\nfor (let k = -3n;k <= 3n; k++) {\n  const newS = ss + k * (bb / gg);\n  const newT = tt - k * (aa / gg);\n  print(`  k=${k}: ${newS}*${aa} + ${newT}*${bb} = ${newS * aa + newT * bb}`);\n}\nprint();",
        "prefix": "const { gcd, xgcd, inverse_mod, Mod } = Sage;\n\nconst pairs = [\n  [48n, 18n],\n  [240n, 46n],\n  [35n, 15n],\n  [101n, 103n]\n];\nprint(\"Extended GCD computations:\");\nfor (const [a, b] of pairs) {\n  const [g, s, t] = xgcd(a, b);\n  print(`\nxgcd(${a}, ${b}):`);\n  print(`  gcd = ${g}`);\n  print(`  Bezout coefficients: s = ${s}, t = ${t}`);\n  print(`  Verification: ${s}*${a} + ${t}*${b} = ${s * a + t * b}`);\n}\nprint();\n\nfunction extendedEuclideanTrace(a, b) {\n  print(`Computing xgcd(${a}, ${b}) step by step:\n`);\n  let oldR = a, r = b;\n  let oldS = 1n, s = 0n;\n  let oldT = 0n, t = 1n;\n  print(`  Initial: ${oldR} = ${oldS}*${a} + ${oldT}*${b}`);\n  print(`           ${r} = ${s}*${a} + ${t}*${b}\n`);\n  let step = 1;\n  while (r !== 0n) {\n    const quotient = oldR / r;\n    const tempR = r;\n    r = oldR - quotient * r;\n    oldR = tempR;\n    const tempS = s;\n    s = oldS - quotient * s;\n    oldS = tempS;\n    const tempT = t;\n    t = oldT - quotient * t;\n    oldT = tempT;\n    print(`  Step ${step}: quotient = ${quotient}`);\n    print(`           ${oldR} = ${oldS}*${a} + ${oldT}*${b}`);\n    if (r !== 0n) {\n      print(`           ${r} = ${s}*${a} + ${t}*${b}`);\n    }\n    print();\n    step++;\n  }\n  if (oldR < 0n) {\n    oldR = -oldR;\n    oldS = -oldS;\n    oldT = -oldT;\n  }\n  print(`  Result: gcd = ${oldR}, s = ${oldS}, t = ${oldT}`);\n  return [oldR, oldS, oldT];\n}\nextendedEuclideanTrace(240n, 46n);\nprint();\n\nfunction findModularInverse(a, n) {\n  const [g, s, _t] = xgcd(a, n);\n  if (g !== 1n) {\n    return null;\n  }\n  return (s % n + n) % n;\n}\nprint(\"Computing modular inverses:\");\nconst invTests = [\n  [3n, 7n],\n  [5n, 12n],\n  [17n, 43n],\n  [6n, 9n]\n];\nfor (const [a, n] of invTests) {\n  const inv = findModularInverse(a, n);\n  const [g, _s, _t] = xgcd(a, n);\n  if (inv !== null) {\n    print(`  ${a}^(-1) mod ${n} = ${inv}`);\n    print(`    Verification: ${a} * ${inv} = ${a * inv} = ${a * inv % n} (mod ${n})\n`);\n  } else {\n    print(`  ${a}^(-1) mod ${n} does not exist (gcd = ${g})\n`);\n  }\n}\nprint(\"Using library inverse_mod function:\");\nprint(`  inverse_mod(3, 7) = ${inverse_mod(3n, 7n)}`);\nprint(`  inverse_mod(17, 43) = ${inverse_mod(17n, 43n)}`);\nprint();\n\nconst p = 61n;\nconst q = 53n;\nconst n = p * q;\nconst phiN = (p - 1n) * (q - 1n);\nconst e = 17n;\nprint(\"RSA Key Generation:\");\nprint(`  p = ${p}, q = ${q}`);\nprint(`  n = ${n}`);\nprint(`  phi(n) = ${phiN}`);\nprint(`  e = ${e}`);\nconst gcdResult = gcd(e, phiN);\nprint(`  gcd(e, phi(n)) = ${gcdResult}`);\nif (gcdResult === 1n) {\n  const [_g, s, _t] = xgcd(e, phiN);\n  const d = (s % phiN + phiN) % phiN;\n  print(`  d = e^(-1) mod phi(n) = ${d}`);\n  print(`\n  Verification: e * d mod phi(n) = ${e * d % phiN}`);\n  const message = 42n;\n  const cipher = message ** e % n;\n  const decrypted = cipher ** d % n;\n  print(`\n  Test encryption/decryption:`);\n  print(`    Message m = ${message}`);\n  print(`    Encrypted: m^e mod n = ${cipher}`);\n  print(`    Decrypted: c^d mod n = ${decrypted}`);\n}\nprint();\n\nfunction solveDiophantine(a, b, c) {\n  const [g, s, t] = xgcd(a, b);\n  if (c % g !== 0n) {\n    return null;\n  }\n  const multiplier = c / g;\n  const x0 = s * multiplier;\n  const y0 = t * multiplier;\n  return [x0, y0];\n}\nprint(`Solving linear Diophantine equations ax + by = c:\n`);\nconst equations = [\n  [12n, 8n, 20n],\n  [15n, 6n, 9n],\n  [14n, 21n, 10n]\n];\nfor (const [a, b, c] of equations) {\n  print(`Equation: ${a}x + ${b}y = ${c}`);\n  const solution = solveDiophantine(a, b, c);\n  const g = gcd(a, b);\n  if (solution) {\n    const [x, y] = solution;\n    print(`  gcd(${a}, ${b}) = ${g} divides ${c} - Solution exists!`);\n    print(`  Particular solution: x = ${x}, y = ${y}`);\n    print(`  Verification: ${a}*${x} + ${b}*${y} = ${a * x + b * y}`);\n    print(`  General solution: x = ${x} + ${b / g}k, y = ${y} - ${a / g}k`);\n  } else {\n    print(`  gcd(${a}, ${b}) = ${g} does NOT divide ${c} - No solution!`);\n  }\n  print();\n}\n\n"
