        "code": "function findRoots(coeffs, n) {\n  const roots = [];\n  for (let x = 0n;x < n; x++) {\n    let sum = 0n;\n    let xPower = 1n;\n    for (const c of coeffs) {\n      sum = (sum + c * xPower) % n;\n      xPower = xPower * x % n;\n    }\n    if (sum === 0n) {\n      roots.push(x);\n    }\n  }\n  return roots;\n}\nprint(\"Solving x^2 - 1 = 0 (mod 7):\");\nconst roots1 = findRoots([-1n, 0n, 1n], 7n);\nprint(`  Roots: ${roots1.join(\", \")}`);\nprint(`  Verification: 1^2 = 1, 6^2 = 36 = 1 (mod 7)\n`);\nprint(\"Solving x^2 - 1 = 0 (mod 8):\");\nconst roots2 = findRoots([-1n, 0n, 1n], 8n);\nprint(`  Roots: ${roots2.join(\", \")}`);\nprint(`  (More roots than degree! This happens when n is not prime.)`);\nprint();",
