        "prefix": "const { gcd, euler_phi, power_mod, factor, divisors, lcm, Mod, Zmod } = Sage;\n\nconst n = 12n;\nprint(`Finding subgroups of (Z/${n}Z, +):\n`);\nfunction findAdditiveSubgroup(g, n) {\n  const subgroup = [];\n  let current = 0n;\n  do {\n    subgroup.push(current);\n    current = (current + g) % n;\n  } while (current !== 0n);\n  return subgroup.sort((a, b) => Number(a - b));\n}\nconst subgroups = new Map;\nfor (let g = 0n;g < n; g++) {\n  const H = findAdditiveSubgroup(g, n);\n  const key = H.join(\",\");\n  if (!subgroups.has(key)) {\n    subgroups.set(key, H);\n    print(`  <${g}> = {${H.join(\", \")}} (order ${H.length})`);\n  }\n}\nprint(`\nTotal: ${subgroups.size} distinct subgroups`);\nprint(`Divisors of ${n}: ${divisors(n).join(\", \")}`);\nprint(\"One subgroup for each divisor!\");\nprint();\n\nconst p = 13n;\nconst groupOrder = p - 1n;\nprint(`(Z/${p}Z)* has order ${groupOrder}`);\nprint(`Divisors of ${groupOrder}: ${divisors(groupOrder).join(\", \")}\n`);\nfunction findMultiplicativeSubgroup(g, p) {\n  const subgroup = [];\n  let current = 1n;\n  do {\n    subgroup.push(current);\n    current = current * g % p;\n  } while (current !== 1n);\n  return subgroup.sort((a, b) => Number(a - b));\n}\nconst multSubgroups = new Map;\nfor (let g = 1n;g < p; g++) {\n  const H = findMultiplicativeSubgroup(g, p);\n  const key = H.join(\",\");\n  if (!multSubgroups.has(key)) {\n    multSubgroups.set(key, { generator: g, elements: H });\n  }\n}\nprint(\"Subgroups of (Z/13Z)*:\");\nfor (const { generator, elements } of multSubgroups.values()) {\n  print(`  <${generator}> = {${elements.join(\", \")}} (order ${elements.length})`);\n}\nprint();\n\nconst cosetMod = 12n;\nconst H = findAdditiveSubgroup(4n, cosetMod);\nprint(`In (Z/${cosetMod}Z, +):`);\nprint(`  Subgroup H = <4> = {${H.join(\", \")}}  (order ${H.length})\n`);\nprint(\"Cosets of H:\");\nconst cosets = new Map;\nfor (let g = 0n;g < cosetMod; g++) {\n  const coset = H.map((h) => (g + h) % cosetMod).sort((a, b) => Number(a - b));\n  const key = coset.join(\",\");\n  if (!cosets.has(key)) {\n    cosets.set(key, g);\n    print(`  ${g} + H = {${coset.join(\", \")}}`);\n  }\n}\nprint(`\nNumber of cosets = ${cosets.size} = ${cosetMod}/${BigInt(H.length)} = |G|/|H|`);\nprint(\"The cosets partition Z/12Z!\");\nprint();\n\nconst lagrangeMod = 15n;\nconst lagrangeH = findAdditiveSubgroup(5n, lagrangeMod);\nprint(`Demonstrating Lagrange's Theorem:`);\nprint(`  G = (Z/${lagrangeMod}Z, +), |G| = ${lagrangeMod}`);\nprint(`  H = <5> = {${lagrangeH.join(\", \")}}, |H| = ${lagrangeH.length}\n`);\nconst lagrangeCosets = [];\nconst seenElements = new Set;\nfor (let g = 0n;g < lagrangeMod; g++) {\n  if (!seenElements.has(g)) {\n    const coset = lagrangeH.map((h) => (g + h) % lagrangeMod).sort((a, b) => Number(a - b));\n    lagrangeCosets.push(coset);\n    for (const elem of coset) {\n      seenElements.add(elem);\n    }\n    print(`  Coset ${lagrangeCosets.length}: ${g} + H = {${coset.join(\", \")}}`);\n  }\n}\nprint(`\nVerification:`);\nprint(`  |G| = ${lagrangeMod}`);\nprint(`  |H| = ${lagrangeH.length}`);\nprint(`  Number of cosets [G:H] = ${lagrangeCosets.length}`);\nprint(`  |G| = |H| * [G:H]? ${lagrangeMod} = ${lagrangeH.length} * ${lagrangeCosets.length} = ${BigInt(lagrangeH.length * lagrangeCosets.length)}`);\nprint();\n\nconst indexMod = 24n;\nprint(`Subgroup indices in (Z/${indexMod}Z, +):\n`);\nconst divisors24 = divisors(indexMod);\nfor (const d of divisors24) {\n  const gen = indexMod / d;\n  const subgroup = findAdditiveSubgroup(gen, indexMod);\n  const index = indexMod / BigInt(subgroup.length);\n  print(`  H = <${gen}>, |H| = ${subgroup.length}, [G:H] = ${indexMod}/${subgroup.length} = ${index}`);\n}\nprint();\n\n"
