        "code": "function findPrimitiveRoots(n) {\n  const phi = euler_phi(n);\n  const units = buildMultiplicativeGroup(n);\n  const primitiveRoots = [];\n  for (const g of units) {\n    if (computeOrder(g, n) === phi) {\n      primitiveRoots.push(g);\n    }\n  }\n  return primitiveRoots;\n}\nconst primRootModuli = [7n, 9n, 11n, 13n, 14n];\nfor (const n of primRootModuli) {\n  const phi = euler_phi(n);\n  const roots = findPrimitiveRoots(n);\n  print(`(Z/${n}Z)*: phi = ${phi}`);\n  if (roots.length > 0) {\n    print(`  Primitive roots: {${roots.join(\", \")}}`);\n    print(`  Count: ${roots.length} = phi(${phi}) = ${euler_phi(phi)}`);\n  } else {\n    print(`  No primitive roots (group is not cyclic)`);\n  }\n  print();\n}",
